-- Prairie Home Furnishings (fictional) - SYNTHETIC demonstration database. Generated by src/engineering/load_db.py
PRAGMA foreign_keys = ON;

CREATE TABLE suppliers (
    "supplier_id" TEXT PRIMARY KEY NOT NULL,
    "supplier_name" TEXT,
    "supplier_class" TEXT,
    "quoted_lead_days" INTEGER,
    "payment_terms" TEXT,
    "region" TEXT,
    "data_status" TEXT
);
CREATE TABLE campaigns (
    "campaign_id" TEXT PRIMARY KEY NOT NULL,
    "campaign_name" TEXT,
    "spend_channel" TEXT,
    "data_status" TEXT
);
CREATE TABLE promotions (
    "promotion_id" TEXT PRIMARY KEY NOT NULL,
    "promotion_name" TEXT,
    "start_date" TEXT,
    "end_date" TEXT,
    "extra_discount_pct" REAL,
    "scope" TEXT,
    "data_status" TEXT
);
CREATE TABLE staff (
    "employee_id" TEXT PRIMARY KEY NOT NULL,
    "role" TEXT,
    "start_date" TEXT,
    "end_date" TEXT,
    "data_status" TEXT
);
CREATE TABLE store_calendar (
    "date" TEXT PRIMARY KEY NOT NULL,
    "store_open" INTEGER
);
CREATE TABLE products (
    "product_id" TEXT PRIMARY KEY NOT NULL,
    "sku" TEXT,
    "product_name" TEXT,
    "manufacturer" TEXT,
    "category" TEXT,
    "subcategory" TEXT,
    "fulfillment_type" TEXT,
    "custom" INTEGER,
    "made_in_canada" INTEGER,
    "options" TEXT,
    "list_price_cad" REAL,
    "compare_at_cad" REAL,
    "unit_cost_cad" REAL,
    "assumed_margin" REAL,
    "supplier_class" TEXT,
    "quoted_lead_days" INTEGER,
    "handle" TEXT,
    "supplier_id" TEXT,
    "reorder_point_current_policy" REAL,
    "order_up_to_current_policy" REAL,
    "on_hand_stock_units" INTEGER,
    "allocated_to_customers_units" INTEGER,
    "holding_cost_rate_annual" REAL,
    "data_status" TEXT,
    FOREIGN KEY ("supplier_id") REFERENCES suppliers(supplier_id) DEFERRABLE INITIALLY DEFERRED,
    CHECK (list_price_cad > 0),
    CHECK (unit_cost_cad > 0)
);
CREATE TABLE customers (
    "customer_id" TEXT PRIMARY KEY NOT NULL,
    "customer_type" TEXT,
    "acquisition_channel" TEXT,
    "created_date" TEXT,
    "postal_area" TEXT,
    "first_order_date" TEXT,
    "last_order_date" TEXT,
    "orders" INTEGER,
    "lifetime_net_sales_cad" REAL,
    "lifetime_gross_profit_cad" REAL,
    "repeat_customer" INTEGER,
    "consultations" INTEGER,
    "campaign_id" TEXT,
    "lead_conversion_status" TEXT,
    "data_status" TEXT,
    FOREIGN KEY ("campaign_id") REFERENCES campaigns(campaign_id) DEFERRABLE INITIALLY DEFERRED
);
CREATE TABLE leads (
    "lead_id" TEXT PRIMARY KEY NOT NULL,
    "lead_date" TEXT,
    "lead_channel" TEXT,
    "customer_id" TEXT,
    "converted" INTEGER,
    "conversion_date" TEXT,
    "lead_status" TEXT,
    "lead_source_detail" TEXT,
    "data_status" TEXT,
    FOREIGN KEY ("customer_id") REFERENCES customers(customer_id) DEFERRABLE INITIALLY DEFERRED
);
CREATE TABLE consultations (
    "consultation_id" TEXT PRIMARY KEY NOT NULL,
    "consultation_date" TEXT,
    "customer_id" TEXT,
    "designer_id" TEXT,
    "consultation_type" TEXT,
    "rooms_in_scope" INTEGER,
    "quotation_amount_cad" REAL,
    "follow_up_count" INTEGER,
    "first_follow_up_days" REAL,
    "designer_hours" REAL,
    "converted" INTEGER,
    "repeat_customer" INTEGER,
    "estimated_conversion_cost_cad" REAL,
    "recommended_categories" TEXT,
    "order_id" TEXT,
    "conversion_date" TEXT,
    "pre_period" INTEGER,
    "conversion_status" TEXT,
    "final_sales_revenue_cad" REAL,
    "days_to_convert" REAL,
    "data_status" TEXT,
    FOREIGN KEY ("customer_id") REFERENCES customers(customer_id) DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("designer_id") REFERENCES staff(employee_id) DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("order_id") REFERENCES orders(order_id) DEFERRABLE INITIALLY DEFERRED
);
CREATE TABLE orders (
    "order_id" TEXT PRIMARY KEY NOT NULL,
    "customer_id" TEXT,
    "order_date" TEXT,
    "sales_channel" TEXT,
    "employee_id" TEXT,
    "room_type" TEXT,
    "consultation_id" TEXT,
    "order_type" TEXT,
    "net_order_value_cad" REAL,
    "gst_cad" REAL,
    "deposit_rate" REAL,
    "tender" TEXT,
    "financed" INTEGER,
    "trade_account" INTEGER,
    "promised_ready_date" TEXT,
    "fulfillment_method" TEXT,
    "protection_plan_cad" REAL,
    "agent_delivery_fee_cad" REAL,
    "promotion_id" TEXT,
    "status" TEXT,
    "ready_date" TEXT,
    "scheduled_date" TEXT,
    "fulfilled_date" TEXT,
    "cancel_date" TEXT,
    "cancel_reason" TEXT,
    "retained_cancellation_fee_cad" REAL,
    "requested_date" TEXT,
    "storage_hold" REAL,
    "carrier" TEXT,
    "damage_flag" REAL,
    "retailer_fulfillment_cost_cad" REAL,
    "carrier_fee_customer_paid_cad" REAL,
    "opening_backlog" INTEGER,
    "total_paid_incl_gst_cad" REAL,
    "order_total_incl_gst_cad" REAL,
    "deposit_required_cad" REAL,
    "deposit_paid_cad" REAL,
