    "ready_delay_days" REAL,
    "handoff_wait_days" REAL,
    "data_status" TEXT,
    FOREIGN KEY ("customer_id") REFERENCES customers(customer_id) DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("employee_id") REFERENCES staff(employee_id) DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("consultation_id") REFERENCES consultations(consultation_id) DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("promotion_id") REFERENCES promotions(promotion_id) DEFERRABLE INITIALLY DEFERRED,
    CHECK (net_order_value_cad > 0),
    CHECK (deposit_rate > 0 AND deposit_rate <= 1)
);
CREATE TABLE sales_transactions (
    "line_id" TEXT PRIMARY KEY NOT NULL,
    "order_id" TEXT,
    "transaction_date" TEXT,
    "customer_id" TEXT,
    "product_id" TEXT,
    "units" INTEGER,
    "list_unit_price_cad" REAL,
    "unit_price_cad" REAL,
    "discount_pct" REAL,
    "discount_reason" TEXT,
    "gross_sales_cad" REAL,
    "net_sales_cad" REAL,
    "unit_cost_cad" REAL,
    "material_variant" TEXT,
    "configuration" TEXT,
    "fulfillment_type" TEXT,
    "supply_source" TEXT,
    "sales_channel" TEXT,
    "employee_id" TEXT,
    "promotion_id" TEXT,
    "consultation_id" TEXT,
    "line_status" TEXT,
    "returned_units" INTEGER,
    "received_date" TEXT,
    "category" TEXT,
    "subcategory" TEXT,
    "manufacturer" TEXT,
    "cogs_cad" REAL,
    "gross_profit_cad" REAL,
    "gross_margin_pct" REAL,
    "opening_backlog" INTEGER,
    "fulfilled_date" TEXT,
    "data_status" TEXT,
    FOREIGN KEY ("order_id") REFERENCES orders(order_id) DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("customer_id") REFERENCES customers(customer_id) DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("product_id") REFERENCES products(product_id) DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("employee_id") REFERENCES staff(employee_id) DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("promotion_id") REFERENCES promotions(promotion_id) DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("consultation_id") REFERENCES consultations(consultation_id) DEFERRABLE INITIALLY DEFERRED,
    CHECK (units > 0),
    CHECK (net_sales_cad <= gross_sales_cad + 0.01),
    CHECK (discount_pct >= 0 AND discount_pct < 1)
);
CREATE TABLE payments (
    "payment_id" TEXT PRIMARY KEY NOT NULL,
    "order_id" TEXT,
    "payment_date" TEXT,
    "payment_type" TEXT,
    "tender" TEXT,
    "amount_incl_gst" REAL,
    "pre_period" INTEGER,
    "data_status" TEXT,
    FOREIGN KEY ("order_id") REFERENCES orders(order_id) DEFERRABLE INITIALLY DEFERRED
);
