    "pre_period" INTEGER,
    "data_status" TEXT,
    FOREIGN KEY ("supplier_id") REFERENCES suppliers(supplier_id) DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("product_id") REFERENCES products(product_id) DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("order_line_id") REFERENCES sales_transactions(line_id) DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("replacement_of") REFERENCES purchase_orders(po_id) DEFERRABLE INITIALLY DEFERRED,
    CHECK (qty_ordered > 0)
